mapper.select:
select ID,GMT_CREATE,GMT_MODIFIED,
       DATA_SOURCE_ID,DATABASE_NAME,SCHEMA_NAME,TABLE_NAME,DELETED,USER_ID,TASK_TYPE,TASK_STATUS,
       TASK_PROGRESS,TASK_NAME,CONTENT,DOWNLOAD_URL
from TASK


        and USER_ID = #{userId}


        and DELETED = #{deleted}


        and TASK_STATUS = #{taskStatus}
